INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('7503cfc8-39a8-4c1b-95ba-b98825aa22dd', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 2, 'A Pobreza de Espírito', NULL, '{"intro": "O apego \u00e0s coisas \u00e9 o peso que impede o voo da alma.", "prayer": "Repita: Eu n\u00e3o sou nada, Tu \u00e9s tudo.", "practice": "Doe algo que voc\u00ea gosta para algu\u00e9m que precise.", "reflection": "S\u00f3 quem nada possui pode possuir Tudo.", "journal_prompt": "O que voc\u00ea ainda tenta segurar com as m\u00e3os fechadas?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;